class WebauthnAttestationPolicy(ManagementModel):
    """Per-tenant WebAuthn attestation policy (D5). One row per tenant; an
    absent row means [`WebauthnAttestationPolicy::default`], which is
    today's behavior unchanged.
    """

    allowed_aaguids: list[str] | None = None
    """`None` = every AAGUID is allowed except `blocked_aaguids`.


    `Some(vec![])` is a deliberate "nothing may register" policy and is
    accepted as such: `evaluate` denies every AAGUID against an empty
    allow-list. Nothing rejects it, precisely because the failure direction
    is safe — a client that sends `[]` when it meant `null` gets a
    locked-down tenant, which is visible immediately, rather than an open
    one, which is not.
    """

    block_revoked_status: bool
    """Deny registration if the MDS entry has ever reported `REVOKED` or any

    `*_COMPROMISE` status (sticky — D8 step 7).
    """

    blocked_aaguids: list[str] | None = None
    """``blocked_aaguids``."""

    min_certification: CertificationLevel | None = None
    """``min_certification``."""

    mode: AttestationMode
    """``mode``."""

    require_fido_certified: bool
    """Require *some* `FIDO_CERTIFIED*` status, any level. Independent of (and

    checked before) `min_certification`.
    """

    unknown_aaguid: UnknownAaguidAction | None = None
    """``unknown_aaguid``."""


class WebauthnPolicy(ManagementModel):
    """WebAuthn ceremony policy.

    One field today. It is a struct rather than a bare field on
    [`SecuritySettings`] so that the next WebAuthn control has an obvious
    home, and so the admin UI can group them.

    The *attestation* policy is deliberately not here: it lives in
    [`crate::models::webauthn_policy::WebauthnAttestationPolicy`], is
    tenant-only, and cannot join this model because AAGUID allow/block lists
    have no "more restrictive than" ordering to validate an override
    against. User verification does, so it can.
    """

    webauthn_user_verification: str
    """How hard the authenticator must prove *who* is present.


    Applies to enrolment and to second-factor authentication. Usernameless
    sign-in is held to `required` whatever this says — see
    [`WebauthnUserVerification`].
    """


